function evaluateCandidates(
  candidates: OriginCandidate[],
  samples: SurfaceSample[],
  acceleration: ReturnType<typeof buildSceneAcceleration>,
  scene: CoverageSceneData,
  options: CoverageOptimizationOptions,
): OriginEvaluation[] {
